const input = $input.first().json;

// Se já veio processado (caminho do áudio)
if (input.phone && input.message) {
  return [{ json: input }];
}

// Caminho texto: processa o webhook bruto
const body = (input.body) || {};
const data = body.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const fromMe = key.fromMe || false;

if (fromMe) return [];

const phone = remoteJid.split('@')[0].replace(/[^0-9]/g, '');
if (!phone) return [];

const msgData = data.message || {};
const message = input.merged_message
  || msgData.conversation
  || (msgData.extendedTextMessage && msgData.extendedTextMessage.text)
  || '';

if (!message.trim()) {
  console.log('[Serena] Descartando execução: mensagem vazia para phone=' + phone);
  return [];
}

return [{
  json: {
    phone: phone,
    pushName: data.pushName || '',
    message: message.trim(),
    instance: body.instance || '',
    timestamp: new Date().toISOString(),
    isAudio: false,
    config: {
      evolution_url: 'https://evolution.agrometadigital.com',
      evolution_instance: 'botier',
      discord_webhook_url: 'PREENCHER_DISCORD_WEBHOOK_URL'
    }
  }
}];

const items = $input.all();
const init = $('Inicializar e Config').first().json;
const lead = (items.length > 0 && items[0].json && items[0].json.Id) ? items[0].json : null;

let historico = [];
try { if (lead && lead.historico_conversa) historico = JSON.parse(lead.historico_conversa); } catch(e) { historico = []; }

const dados_qual = {
  area_atuacao:           lead ? (lead.area_atuacao || null) : null,
  producao_diaria_litros: lead ? (lead.producao_diaria_litros || null) : null,
  cidade:                 lead ? (lead.cidade || null) : null,
  estado:                 lead ? (lead.estado || null) : null,
  vacas_lactacao:         lead ? (lead.vacas_lactacao || null) : null,
  cabecas_gado:           lead ? (lead.cabecas_gado || null) : null,
  sistema_producao:       lead ? (lead.sistema_producao || null) : null,
  preco_litro:            null,
  situacao_silagem:       null,
  processamento_grao:     null,
  intencao_compra:        null
};

try {
  if (lead && lead.dados_qualificacao) {
    const dq = JSON.parse(lead.dados_qualificacao);
    ['vacas_lactacao','cabecas_gado','sistema_producao','preco_litro','situacao_silagem','processamento_grao','intencao_compra'].forEach(function(k) {
      if (dq[k] !== undefined && dq[k] !== null) dados_qual[k] = dq[k];
    });
  }
} catch(e) {}

const leadNome = lead ? (lead.nome || init.pushName || '') : (init.pushName || '');

return [{json: {
  phone: init.phone,
  pushName: init.pushName,
  lead_first_name: leadNome.split(' ')[0] || '',
  message: init.message,
  config: init.config,
  timestamp: init.timestamp,
  lead_exists: lead !== null,
  lead_id: lead ? lead.Id : null,
  historico: historico,
  dados_qualificacao: dados_qual,
  pontuacao: lead ? (lead.pontuacao_qualificacao || 0) : 0,
  dados_completos: lead ? (lead.dados_completos === true || lead.dados_completos === 1) : false,
  aguardando_especialista: lead ? (lead.aguardando_especialista === true || lead.aguardando_especialista === 1) : false
}}];

const ctx = $input.first().json;

const dadosColetados = Object.entries(ctx.dados_qualificacao || {})
  .filter(function(e) { return e[1] !== null && e[1] !== undefined; })
  .map(function(e) { return e[0] + ': ' + e[1]; })
  .join(', ') || 'nenhum dado coletado ainda';

// Separamos o contexto dinâmico da mensagem do produtor
const contexto_sistema = '[CONTEXTO DINÂMICO DESTE LEAD]\n' 
  + 'Nome do Lead: ' + (ctx.lead_first_name || '') + '\n'
  + 'Dados já coletados: ' + dadosColetados;

return [{json: Object.assign({}, ctx, {
  contexto_sistema: contexto_sistema
})}];

const novoLead = $input.first().json;
const ctx = $('Preparar Contexto Lead').first().json;
return [{json: Object.assign({}, ctx, { lead_id: novoLead.Id, lead_exists: true })}];

const agentResp = $input.first().json;
const ctx = $('Preparar Input Agente').first().json;

const rawText = agentResp.output || '{}';
const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { mensagem_whatsapp: cleaned, novos_dados: {}, acionar_especialista: false };
}

const mensagem = parsed.mensagem_whatsapp || '';
const novos_dados = parsed.novos_dados || {};
const acionar_especialista_llm = parsed.acionar_especialista === true;
const enviar_video = parsed.enviar_video_geral === true;
const dados_qual = Object.assign({}, ctx.dados_qualificacao, novos_dados);

// ── Scoring ──────────────────────────────────────────────────────────────
let score = 0;

const area = (dados_qual.area_atuacao || '').toLowerCase();
if (area.includes('leite'))                                      score += 30;
else if (area.includes('corte') || area.includes('misto'))      score += 15;
else if (area.includes('prestador') || area.includes('silagem')) score += 5;

const rebanho = Number(dados_qual.rebanho) || 0;
if (area.includes('prestador'))  score += 5;
else if (rebanho > 100)          score += 40;
else if (rebanho >= 50)          score += 25;
else if (rebanho > 0)            score += 5;

const silagem = dados_qual.situacao_silagem;
const silagemNorm = (silagem || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
if (silagemNorm === 'propria' || silagemNorm === 'empreiteiro') score += 25;
else if (silagemNorm === 'compra_pronta')                       score += 10;
else if (area.includes('prestador'))                            score += 25;

const intencao = dados_qual.intencao_compra;
if (intencao === '60dias')           score += 40;
else if (intencao === '120dias')     score += 15;
else if (intencao === 'curiosidade') score += 5;

// ── Temperatura ──────────────────────────────────────────────────────────
const algumDadoColetado = Object.values(dados_qual).some(function(v) { return v !== null && v !== undefined; });
let temperatura = 'FRIO';
if (algumDadoColetado) {
  if (score >= 90)      temperatura = 'QUENTE';
  else if (score >= 60) temperatura = 'MORNO';
  else if (score >= 30) temperatura = 'FRIO';
  else                  temperatura = 'DESCARTADO';
}

// CLIENTE_ATUAL — sobrescreve após o cálculo normal
if (intencao === 'cliente_atual') {
  score = 0;
  temperatura = 'CLIENTE_ATUAL';
}

// ── Dados completos ───────────────────────────────────────────────────────
const camposObrigatorios = ['area_atuacao', 'rebanho', 'producao_diaria_litros', 'preco_litro', 'situacao_silagem', 'processamento_grao', 'cidade', 'estado'];
const dados_completos = camposObrigatorios.every(function(c) {
  return dados_qual[c] !== null && dados_qual[c] !== undefined && dados_qual[c] !== '';
});

return [{json: Object.assign({}, ctx, {
  mensagem_whatsapp: mensagem,
  novos_dados: novos_dados,
  dados_qualificacao: dados_qual,
  pontuacao: score,
  temperatura: temperatura,
  dados_completos: dados_completos,
  acionar_especialista: acionar_especialista_llm,
  enviar_video: enviar_video // <-- INCLUIR AQUI
})}];

const ctx = $input.first().json;
const dq  = ctx.dados_qualificacao || {};

const patchBody = {
  // colunas individuais NocoDB V2
  area_atuacao:           dq.area_atuacao           || null,
  producao_diaria_litros: dq.producao_diaria_litros || null,
  cidade:                 dq.cidade                 || null,
  estado:                 dq.estado                 || null,
  vacas_lactacao:         dq.vacas_lactacao         || null,
  cabecas_gado:           dq.cabecas_gado           || null,
  sistema_producao:       dq.sistema_producao       || null,

  // JSON consolidado
  dados_qualificacao:     JSON.stringify(dq),

  // controle
  pontuacao_qualificacao: ctx.pontuacao  || 0,
  temperatura:            ctx.temperatura || 'FRIO',
  dados_completos:        ctx.dados_completos || false,
  aguardando_especialista: ctx.acionar_especialista || false,
  ultima_mensagem:        ctx.timestamp,
  em_atendimento:         true
};

return [{json: Object.assign({}, ctx, { patchBody: patchBody })}];

// 1. Nome e mensagem
const primeiroNome = $('Preparar Contexto Lead').first().json.lead_first_name || '';
let mensagem = $('Parsear Resposta e Calcular Score').first().json.mensagem_whatsapp || '';
mensagem = mensagem
  .replace(/\[nome\]/gi, primeiroNome)
  .replace(/\{nome\}/gi, primeiroNome);

const LIMITE = 120;

// Divide sentenças sem quebrar números (R$ 240.000, 75hp, 4.000 RPM etc.)
// Só quebra em . ! ? quando o próximo caractere não-espaço for maiúsculo ou fim de string
function splitSentencas(texto) {
  var resultado = [];
  var atual = '';
  var i = 0;
  while (i < texto.length) {
    atual += texto[i];
    if ('.!?'.indexOf(texto[i]) !== -1) {
      var j = i + 1;
      // Avança pelos espaços à frente
      while (j < texto.length && texto[j] === ' ') { j++; }
      var proximoEhMaiusculo = j >= texto.length || /[A-ZÁÉÍÓÚÀÂÊÔÃÕÜÇ"'(]/.test(texto[j]);
      if (proximoEhMaiusculo) {
        resultado.push(atual.trim());
        atual = '';
        i = j - 1; // pula os espaços consumidos
      }
    }
    i++;
  }
  if (atual.trim()) resultado.push(atual.trim());
  return resultado.filter(function(p) { return p.length > 0; });
}

// Agrupa sentenças respeitando o limite de caracteres
function agrupar(sentencas) {
  var grupos = [];
  var atual = '';
  sentencas.forEach(function(s) {
    var candidato = atual ? atual + ' ' + s : s;
    if (candidato.length <= LIMITE) {
      atual = candidato;
    } else {
      if (atual) grupos.push(atual);
      atual = s; // mantém a sentença mesmo se ultrapassar o limite
    }
  });
  if (atual) grupos.push(atual);
  return grupos;
}

// FIX PRINCIPAL: divide por \n simples (não só \n\n)
// A Ana gera mensagens com \n entre frases, não \n\n
var linhas = mensagem
  .split('\n')
  .map(function(l) { return l.trim(); })
  .filter(function(l) { return l.length > 0; });

var partes = [];
linhas.forEach(function(linha) {
  if (linha.length <= LIMITE) {
    partes.push(linha);
  } else {
    agrupar(splitSentencas(linha)).forEach(function(g) { partes.push(g); });
  }
});

var resultado = partes.length > 0 ? partes : [mensagem];
return resultado.map(function(p) { return { json: { output: p } }; });

const texto = $json.output || '';
const delay = Math.min(5000, Math.max(1000, Math.floor(texto.length / 50) * 1000));
return [{ json: { ...$json, delay_ms: delay } }];

